    if (argc != 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *data = malloc(size);
    if (!data) { perror("malloc"); return 1; }
    fread(data, 1, size, f);
    fclose(f);

    ssh_buffer buf = ssh_buffer_new();
    if (!buf) {
        fprintf(stderr, "Failed to create buffer\n");
        return 1;
    }

    ssh_buffer_add_data(buf, data, size);

    uint32_t val32;
    uint16_t val16;
    uint8_t val8;
    uint64_t val64;
    char *cstring = NULL;
    ssh_string str = NULL;
    void *pdata = NULL;
    size_t plen = 0;

    /* Test 's' format - C string */
    ssh_buffer buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    int rc = _ssh_buffer_unpack(buf2, "s", -1, &cstring, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) { printf("s OK\n"); free(cstring); cstring = NULL; }
    ssh_buffer_free(buf2);

    /* Test 'S' format - SSH string */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "S", -1, &str, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK && str) { printf("S OK\n"); ssh_string_free(str); str = NULL; }
    ssh_buffer_free(buf2);

    /* Test 'b' format */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "b", -1, &val8, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) printf("b OK: %u\n", val8);
    ssh_buffer_free(buf2);

    /* Test 'w' format */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "w", -1, &val16, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) printf("w OK: %u\n", val16);
    ssh_buffer_free(buf2);

    /* Test 'd' format */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "d", -1, &val32, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) printf("d OK: %u\n", val32);
    ssh_buffer_free(buf2);

    /* Test 'q' format */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "q", -1, &val64, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) printf("q OK\n");
    ssh_buffer_free(buf2);

    /* Test 'P' format */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    plen = size;
    rc = _ssh_buffer_unpack(buf2, "P", -1, plen, &pdata, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) { printf("P OK\n"); free(pdata); pdata = NULL; }
    ssh_buffer_free(buf2);

    /* Test 'ds' format - dword then C string */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "ds", -1, &val32, &cstring, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) { printf("ds OK\n"); free(cstring); cstring = NULL; }
    ssh_buffer_free(buf2);

    /* Test 'dS' format */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "dS", -1, &val32, &str, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) { printf("dS OK\n"); ssh_string_free(str); str = NULL; }
    ssh_buffer_free(buf2);

    /* Test 'dds' format */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "dds", -1, &val32, &val32, &cstring, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) { printf("dds OK\n"); free(cstring); cstring = NULL; }
    ssh_buffer_free(buf2);

    /* Test 'ddd' format */
    buf2 = ssh_buffer_new();
    ssh_buffer_add_data(buf2, data, size);
    rc = _ssh_buffer_unpack(buf2, "ddd", -1, &val32, &val32, &val32, SSH_BUFFER_PACK_END);
    if (rc == SSH_OK) printf("ddd OK\n");
    ssh_buffer_free(buf2);

    ssh_buffer_free(buf);
    free(data);
    printf("All tests passed without crash\n");
    return 0;
}
